#include <bits/stdc++.h>
using namespace std;

struct UnionFind {
    unordered_map<int, int> parents;
    unordered_map<int, int> sizes;

    int find(int a) {
        auto getOrDefault = [&](int value) {
            auto it = parents.find(value);
            if (it == parents.end()) return value;
            return it->second;
        };

        int parent = getOrDefault(a);
        while (parent != getOrDefault(parent)) {
            parents[parent] = getOrDefault(getOrDefault(parent));
            parent = parents[parent];
        }
        return parent;
    }

    void unionSet(int a, int b) {
        int fa = find(a);
        int fb = find(b);
        if (fa != fb) {
            parents[fa] = fb;
            int sizeFa = sizes.count(fa) ? sizes[fa] : 1;
            int sizeFb = sizes.count(fb) ? sizes[fb] : 1;
            sizes[fb] = sizeFb + sizeFa;
        }
    }

    bool connected(int a, int b) {
        return find(a) == find(b);
    }

    int getSize(int a) {
        int fa = find(a);
        auto it = sizes.find(fa);
        return it == sizes.end() ? 1 : it->second;
    }
};

struct UnionFindArray {
    int n;
    vector<int> parents;

    UnionFindArray(int n_) : n(n_), parents(n_ + 1) {
        for (int i = 0; i <= n; ++i) parents[i] = i;
    }

    int find(int a) {
        int parent = parents[a];
        while (parent != parents[parent]) {
            parents[parent] = parents[parents[parent]];
            parent = parents[parent];
        }
        return parent;
    }

    void unionSet(int a, int b) {
        int fa = find(a);
        int fb = find(b);
        if (fa != fb) parents[fa] = fb;
    }

    bool connected(int a, int b) {
        return find(a) == find(b);
    }
};

struct Trie {
    struct Node {
        bool hasWord;
        unordered_map<char, Node*> children;
        Node() : hasWord(false) {}
    };

    Node* root;

    Trie() {
        root = new Node();
    }

    void insert(const string& word) {
        Node* node = root;
        for (char c : word) {
            if (!node->children.count(c)) {
                node->children[c] = new Node();
            }
            node = node->children[c];
        }
        node->hasWord = true;
    }

    Node* findNode(const string& prefix) {
        Node* node = root;
        for (char c : prefix) {
            if (!node->children.count(c)) return nullptr;
            node = node->children[c];
        }
        return node;
    }

    bool search(const string& word) {
        Node* node = findNode(word);
        return node ? node->hasWord : false;
    }

    bool startsWith(const string& prefix) {
        return findNode(prefix) != nullptr;
    }
};

struct BinaryIndexedTree {
    vector<int> bit;

    BinaryIndexedTree(int n) {
        bit.assign(n + 1, 0);
    }

    BinaryIndexedTree(const vector<int>& nums) {
        bit.assign((int)nums.size() + 1, 0);
        vector<int> prefix(bit.size(), 0);
        for (int i = 1; i <= (int)nums.size(); ++i) {
            prefix[i] = prefix[i - 1] + nums[i - 1];
            bit[i] = prefix[i] - prefix[i - lowbit(i)];
        }
    }

    int lowbit(int x) {
        return x & -x;
    }

    int query(int index) {
        int result = 0;
        int i = index + 1;
        while (i > 0) {
            result += bit[i];
            i -= lowbit(i);
        }
        return result;
    }

    void add(int index, int x) {
        int i = index + 1;
        while (i < (int)bit.size()) {
            bit[i] += x;
            i += lowbit(i);
        }
    }

    void update(int index, int x) {
        int value = query(index) - query(index - 1);
        add(index, x - value);
    }

    string toString() {
        vector<int> arr(bit.size() - 1);
        for (int i = 0; i < (int)arr.size(); ++i) {
            arr[i] = query(i) - query(i - 1);
        }
        // simple representation
        string s = "[";
        for (int i = 0; i < (int)arr.size(); ++i) {
            if (i) s += ", ";
            s += to_string(arr[i]);
        }
        s += "]";
        return s;
    }
};

struct BinaryIndexedTreeMax {
