long long fastPow(long long a, long long exp, long long mod) {
    long long result = 1 % mod;
    long long base = a % mod;
    long long remain = exp;
    while (remain != 0) {
        if (remain % 2 == 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        remain /= 2;
    }
    return result;
}

