        auto getOrDefault = [&](int value) {
            auto it = parents.find(value);
            if (it == parents.end()) return value;
            return it->second;
        };
        int parent = getOrDefault(a);
        while (parent != getOrDefault(parent)) {
            parents[parent] = getOrDefault(getOrDefault(parent));
            parent = parents[parent];
        }
        return parent;
    }

