struct BinaryIndexedTree {
    vector<int> bit;

    BinaryIndexedTree(int n) {
        bit.assign(n + 1, 0);
    }

    BinaryIndexedTree(const vector<int>& nums) {
        bit.assign((int)nums.size() + 1, 0);
        vector<int> prefix(bit.size(), 0);
        for (int i = 1; i <= (int)nums.size(); ++i) {
            prefix[i] = prefix[i - 1] + nums[i - 1];
            bit[i] = prefix[i] - prefix[i - lowbit(i)];
        }
    }

    int lowbit(int x) {
        return x & -x;
    }

    int query(int index) {
        int result = 0;
        int i = index + 1;
        while (i > 0) {
            result += bit[i];
            i -= lowbit(i);
        }
        return result;
    }

    void add(int index, int x) {
        int i = index + 1;
        while (i < (int)bit.size()) {
            bit[i] += x;
            i += lowbit(i);
        }
    }

    void update(int index, int x) {
        int value = query(index) - query(index - 1);
        add(index, x - value);
    }
};

