vector<int> unify(const vector<int>& nums) {
    vector<int> sorted = nums;
    sort(sorted.begin(), sorted.end());
    sorted.erase(unique(sorted.begin(), sorted.end()), sorted.end());
    unordered_map<int,int> numToIndex;
    for (int i = 0; i < (int)sorted.size(); ++i) {
        numToIndex[sorted[i]] = i;
    }
    vector<int> res(nums.size());
    for (int i = 0; i < (int)nums.size(); ++i) {
        res[i] = numToIndex[nums[i]];
    }
    return res;
}

int lengthOfLIS(const vector<int>& numsInput) {
    vector<int> nums = unify(numsInput);
    BinaryIndexedTreeMax bit(nums.size() + 1);
    int result = 0;
    for (int num : nums) {
        int len = bit.query(num - 1) + 1;
        bit.update(num, len);
        result = max(result, len);
    }
    return result;
}

