int requiredLen(int n, long long x) {
    const int MAX = 10000;
    deque<long long> queue = toArrayDeque(vector<long long>{x});
    int step = 0;
    while (!queue.empty()) {
        vector<long long> next;
        while (!queue.empty()) {
            long long num = queue.front();
            queue.pop_front();
            if (num < 0LL) {
                return step;
            }
            string str = to_string(num);
            if ((int)str.size() == n) {
                return step;
            }
            if ((int)str.size() > n) {
                continue;
            }
            vector<bool> digits(10, false);
            for (char ch : str) {
                int d = charToDigit(ch);
                if (d <= 1 || digits[d]) continue;
                digits[d] = true;
                next.push_back(num * d);
            }
        }
        sort(next.begin(), next.end(), greater<long long>());
        int limit = min(MAX, (int)next.size());
        for (int i = 0; i < limit; ++i) {
            queue.push_back(next[i]);
        }
        step++;
    }
    return -1;
}

int requiredLen1(int n, long long x) {
    deque<long long> queue = toArrayDeque(vector<long long>{x});
    int step = 0;
    while (!queue.empty()) {
        deque<pair<long long,string>> nextQueue;
        int maxLen = 0;
        while (!queue.empty()) {
            long long num = queue.front();
            queue.pop_front();
            if (num < 0LL) {
                return step;
            }
            string str = to_string(num);
            if ((int)str.size() == n) {
                return step;
            }
            if ((int)str.size() > n) {
                continue;
            }
            vector<bool> digits(10, false);
            for (char ch : str) {
                digits[charToDigit(ch)] = true;
            }
            for (int d = 2; d < 10; ++d) {
                if (!digits[d]) continue;
                long long nextNum = num * d;
                string nextStr = to_string(nextNum);
                nextQueue.emplace_back(nextNum, nextStr);
                maxLen = max(maxLen, (int)nextStr.size());
            }
        }
        for (auto &p : nextQueue) {
            long long num = p.first;
            string &str = p.second;
            queue.push_back(num);
        }
        step++;
    }
    return -1;
}

