class SparseTableMax {
private:
    vector<vector<int>> st;
    vector<int> nums;
public:
    SparseTableMax(const vector<int>& nums): nums(nums) {
        int n = nums.size();
        int logN = 31 - __builtin_clz(n);
        st.assign(n*2, vector<int>(logN+1,0));
        for (int i=0;i<n;i++) st[i][0] = nums[i];
        for (int j=1;j<=logN;j++) {
            for (int i=0;i<n;i++) {
                st[i][j] = st[i][j-1];
                if (i + (1<<(j-1)) < n) {
                    st[i][j] = max(st[i][j], st[i + (1<<(j-1))][j-1]);
                }
            }
        }
    }
    int query(int left, int right) {
        if (left > right) return -1;
        int len = right - left + 1;
        int k = 31 - __builtin_clz(len);
        return max(st[left][k], st[right - (1<<k) + 1][k]);
    }
};

