class PrefixSum2D {
private:
    vector<vector<int>> prefix;
public:
    PrefixSum2D(const vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        prefix.assign(m+1, vector<int>(n+1,0));
        for (int i=0;i<m;i++) {
            int row = 0;
            for (int j=0;j<n;j++) {
                row += grid[i][j];
                prefix[i+1][j+1] = prefix[i][j+1] + row;
            }
        }
    }
    int query(int up, int left, int bottom, int right) {
        return prefix[up][left] + prefix[bottom+1][right+1] -
               prefix[bottom+1][left] - prefix[up][right+1];
    }
};

