            for (int i = 0; i < n; ++i) {
                st[i][j] = st[i][j - 1];
                if (i + (1 << (j - 1)) < n) {
                    st[i][j] = min(st[i][j], st[i + (1 << (j - 1))][j - 1]);
                }
            }
        }
    }

    int query(int left, int right) {
        if (left > right) return -1;
        int len = right - left + 1;
        int k = 31 - __builtin_clz(len);
        return min(st[left][k], st[right - (1 << k) + 1][k]);
    }
};

