struct UnionFind {
    unordered_map<int, int> parents;
    unordered_map<int, int> sizes;

    int find(int a) {
        auto getOrDefault = [&](int value) {
            auto it = parents.find(value);
            if (it == parents.end()) return value;
            return it->second;
        };

        int parent = getOrDefault(a);
        while (parent != getOrDefault(parent)) {
            parents[parent] = getOrDefault(getOrDefault(parent));
            parent = parents[parent];
        }
        return parent;
    }

    void unionSet(int a, int b) {
        int fa = find(a);
        int fb = find(b);
        if (fa != fb) {
            parents[fa] = fb;
            int sizeFa = sizes.count(fa) ? sizes[fa] : 1;
            int sizeFb = sizes.count(fb) ? sizes[fb] : 1;
            sizes[fb] = sizeFb + sizeFa;
        }
    }

    bool connected(int a, int b) {
        return find(a) == find(b);
    }

    int getSize(int a) {
        int fa = find(a);
        auto it = sizes.find(fa);
        return it == sizes.end() ? 1 : it->second;
    }
};

