struct BinaryIndexedTree {
    vector<int> bit;

    BinaryIndexedTree(int n) {
        bit.assign(n + 1, 0);
    }

    BinaryIndexedTree(const vector<int>& nums) {
        bit.assign(nums.size() + 1, 0);
        vector<int> prefix(bit.size(), 0);
        for (int i = 1; i <= (int)nums.size(); ++i) {
            prefix[i] = prefix[i - 1] + nums[i - 1];
            bit[i] = prefix[i] - prefix[i - lowbit(i)];
        }
    }

    int lowbit(int x) {
        return x & -x;
    }

    int query(int index) {
        int result = 0;
        int i = index + 1;
        while (i > 0) {
            result += bit[i];
            i -= lowbit(i);
        }
        return result;
    }

    void add(int index, int x) {
        int i = index + 1;
        while (i < (int)bit.size()) {
            bit[i] += x;
            i += lowbit(i);
        }
    }

    void update(int index, int x) {
        int value = query(index) - query(index - 1);
        add(index, x - value);
    }

    string toString() {
        int n = (int)bit.size() - 1;
        vector<int> arr(n);
        for (int i = 0; i < n; ++i) {
            arr[i] = query(i) - query(i - 1);
        }
        stringstream ss;
        ss << "[";
        for (int i = 0; i < n; ++i) {
            if (i) ss << ", ";
            ss << arr[i];
        }
        ss << "]";
        return ss.str();
    }
};

