    unordered_map<int,int> numToIndex;
    for (int i = 0; i < (int)sorted.size(); ++i) {
        numToIndex[sorted[i]] = i;
    }
    vector<int> res(nums.size());
    for (int i = 0; i < (int)nums.size(); ++i) {
        res[i] = numToIndex[nums[i]];
    }
    return res;
}

